        },
        {
          "source": "netlist",
          "quote": "(net (name \"NET0011\") ... (node (ref \"U2\") (pin \"6\") ...) (node (ref \"U4\") (pin \"6\") ...))"
        },
        {
          "source": "netlist",
          "quote": "(net (name \"NET0012\") ... (node (ref \"U2\") (pin \"7\") ...) (node (ref \"U4\") (pin \"7\") ...))"
        },
        {
          "source": "spec",
          "quote": "an ATtiny-driven fan controller"
        }
      ],
